    port: int = 0

fn make(threaded: bool) -> Settings:
    s = Settings()                             # made with the thread_shared layout: the capture below shares it
    if threaded:
        h = thread.spawn(owns fn() thread_shared s: println(s.port))
        h.join()
        return Settings(port=s.port)
    return s                                   # held alone: a block 16 or more bytes bigger than a Settings's

fn main():
    c = make(false)
    println(c.port)                            # c ends here

class Node:
    hp: int = 10

class Camera:
    target: weakref Node = None

static ORIGIN: Node = Node()

fn aim(ref mut cam: Camera, enemies: Array[Node], i: int):
    if i < enemies.len():
        cam.target = weakref enemies[i]
    else:
        cam.target = weakref ORIGIN          # rest on the origin marker

fn shoot(ref mut cam: Camera):
    if cam.target exists as ref mut n:       # E3023: cam.target may hold a link to ORIGIN
        n.hp -= 1

open class Entity:
    id: int = 0

class Enemy(Entity):
    hp: int = 100
    path: Array[int] = []

fn snapshot(all: Array[thread_shared Entity]) -> Array[thread_shared Entity]:
    out: Array[thread_shared Entity] = []
    for e in all:
        out.push(thread_shared e)          # one more owner each, after the values were handed over
    return out

